struct ApiKeyMiddleware: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard request.headers.first(name: "X-Api-Key") != nil else {
            throw Abort(.unauthorized)                 // stop the chain
        }
        return try await next.respond(to: request)      // forward
    }
}
// app.middleware.use(ApiKeyMiddleware())

protocol Handler { func handle(_ request: Request) -> Response? }

struct Chain {
    let handlers: [any Handler]

    func dispatch(_ request: Request) -> Response {
        for handler in handlers {
            if let response = handler.handle(request) { return response }  // stop
        }
        return .unhandled                                   // terminal outcome
    }
}

